-- daily_task_items -- isi kegiatan per periode (HARI/MINGGU/BULAN)
create table if not exists public.daily_task_items (
  id bigint generated by default as identity primary key,
  period text not null,
  text text not null,
  sort_order int not null default 0,
  created_at timestamptz default now()
);
create index if not exists daily_task_items_period_idx on public.daily_task_items(period, sort_order);
create unique index if not exists daily_task_items_period_sort_uq on public.daily_task_items(period, sort_order);
alter table public.daily_task_items enable row level security;
drop policy if exists "daily_task_items_read" on public.daily_task_items;
create policy "daily_task_items_read" on public.daily_task_items for select using (true);
drop policy if exists "daily_task_items_insert" on public.daily_task_items;
create policy "daily_task_items_insert" on public.daily_task_items for insert with check (true);
drop policy if exists "daily_task_items_update" on public.daily_task_items;
create policy "daily_task_items_update" on public.daily_task_items for update using (true) with check (true);
drop policy if exists "daily_task_items_delete" on public.daily_task_items;
create policy "daily_task_items_delete" on public.daily_task_items for delete using (true);
